CREATE TABLE `google_sheet_sync_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sourcing_order_id` bigint(20) unsigned DEFAULT NULL,
  `status` enum('success','error') NOT NULL DEFAULT 'success',
  `action` varchar(255) NOT NULL DEFAULT 'append',
  `error_message` text DEFAULT NULL,
  `error_code` varchar(255) DEFAULT NULL,
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`data`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `google_sheet_sync_logs_sourcing_order_id_foreign` (`sourcing_order_id`),
  KEY `google_sheet_sync_logs_status_created_at_index` (`status`,`created_at`),
  CONSTRAINT `google_sheet_sync_logs_sourcing_order_id_foreign` FOREIGN KEY (`sourcing_order_id`) REFERENCES `sourcing_orders` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=137 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

