CREATE TABLE `quotations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sourcing_request_id` bigint(20) unsigned NOT NULL,
  `amount` decimal(8,2) NOT NULL,
  `unit_price` decimal(8,2) NOT NULL,
  `commission_service` decimal(8,2) NOT NULL,
  `unit_weight` decimal(8,2) NOT NULL,
  `weight_unit` varchar(255) NOT NULL DEFAULT 'g',
  `delivery_cost_china` decimal(8,2) NOT NULL,
  `real_product_image` varchar(255) DEFAULT NULL,
  `estimated_product_cost` decimal(10,2) DEFAULT NULL COMMENT 'Coût estimé du produit',
  `estimated_shipping_cost` decimal(10,2) DEFAULT NULL COMMENT 'Coût estimé de transport',
  `estimated_other_costs` decimal(10,2) DEFAULT NULL COMMENT 'Autres coûts estimés',
  `estimated_net_profit` decimal(10,2) DEFAULT NULL COMMENT 'Marge nette estimée (auto-calculée)',
  `currency` varchar(255) NOT NULL,
  `actual_sourcing_location` varchar(255) DEFAULT NULL,
  `sourcing_note` text DEFAULT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'pending',
  `negotiation_notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `assigned_to_admin_id` bigint(20) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `quotations_sourcing_request_id_foreign` (`sourcing_request_id`),
  KEY `quotations_user_id_foreign` (`user_id`),
  KEY `quotations_assigned_to_admin_id_foreign` (`assigned_to_admin_id`),
  CONSTRAINT `quotations_assigned_to_admin_id_foreign` FOREIGN KEY (`assigned_to_admin_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `quotations_sourcing_request_id_foreign` FOREIGN KEY (`sourcing_request_id`) REFERENCES `sourcing_requests` (`id`) ON DELETE CASCADE,
  CONSTRAINT `quotations_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

