CREATE TABLE `refund_requests` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sourcing_order_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned NOT NULL,
  `assigned_to_admin_id` bigint(20) unsigned DEFAULT NULL,
  `type` enum('full','partial') NOT NULL DEFAULT 'full',
  `status` enum('pending','under_review','approved','processed','rejected') NOT NULL DEFAULT 'pending',
  `amount_requested` decimal(15,2) NOT NULL,
  `damaged_quantity` int(11) DEFAULT NULL,
  `amount_approved` decimal(15,2) DEFAULT NULL,
  `reason_category` varchar(255) NOT NULL,
  `reason_description` text NOT NULL,
  `admin_notes` text DEFAULT NULL,
  `evidence_paths` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`evidence_paths`)),
  `refund_proof_path` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `refund_requests_sourcing_order_id_foreign` (`sourcing_order_id`),
  KEY `refund_requests_user_id_foreign` (`user_id`),
  KEY `refund_requests_assigned_to_admin_id_foreign` (`assigned_to_admin_id`),
  CONSTRAINT `refund_requests_assigned_to_admin_id_foreign` FOREIGN KEY (`assigned_to_admin_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `refund_requests_sourcing_order_id_foreign` FOREIGN KEY (`sourcing_order_id`) REFERENCES `sourcing_orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `refund_requests_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

