CREATE TABLE `shipping_companies` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `tracking_provider` varchar(255) DEFAULT NULL,
  `google_sheet_id` varchar(255) DEFAULT NULL,
  `sheet_name` varchar(255) DEFAULT 'sourcing',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `lark_app_id` varchar(255) DEFAULT NULL,
  `lark_app_secret` varchar(255) DEFAULT NULL,
  `lark_base_token` varchar(255) DEFAULT NULL,
  `lark_table_id` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

