CREATE TABLE `shipping_fee_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `shipping_fee_id` bigint(20) unsigned NOT NULL,
  `transport_type` varchar(255) NOT NULL,
  `item_style` varchar(255) NOT NULL,
  `price_per_kg` decimal(10,2) DEFAULT NULL,
  `estimation_days` varchar(255) DEFAULT NULL,
  `estimation_unit` varchar(255) NOT NULL DEFAULT 'days',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `shipping_fee_items_shipping_fee_id_foreign` (`shipping_fee_id`),
  CONSTRAINT `shipping_fee_items_shipping_fee_id_foreign` FOREIGN KEY (`shipping_fee_id`) REFERENCES `shipping_fees` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=169 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

