CREATE TABLE `shipping_fees` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `country_id` bigint(20) unsigned NOT NULL,
  `sea_fee` decimal(10,2) DEFAULT NULL,
  `train_fee` decimal(10,2) DEFAULT NULL,
  `air_normal_fee` decimal(10,2) DEFAULT NULL,
  `air_brand_fee` decimal(10,2) DEFAULT NULL,
  `air_battery_fee` decimal(10,2) DEFAULT NULL,
  `air_liquid_fee` decimal(10,2) DEFAULT NULL,
  `currency` varchar(255) NOT NULL DEFAULT 'USD',
  `unit` varchar(255) NOT NULL DEFAULT 'kg',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `air_arrival_time` varchar(255) DEFAULT NULL,
  `sea_arrival_time` varchar(255) DEFAULT NULL,
  `train_arrival_time` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `shipping_fees_country_id_foreign` (`country_id`),
  CONSTRAINT `shipping_fees_country_id_foreign` FOREIGN KEY (`country_id`) REFERENCES `countries` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

