CREATE TABLE `sourcing_order_media` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sourcing_order_id` bigint(20) unsigned NOT NULL,
  `file_path` varchar(255) NOT NULL,
  `file_name` varchar(255) DEFAULT NULL,
  `file_type` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sourcing_order_media_sourcing_order_id_foreign` (`sourcing_order_id`),
  CONSTRAINT `sourcing_order_media_sourcing_order_id_foreign` FOREIGN KEY (`sourcing_order_id`) REFERENCES `sourcing_orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



CREATE TABLE `sourcing_orders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `assigned_to_admin_id` bigint(20) unsigned DEFAULT NULL,
  `shipping_company_id` bigint(20) unsigned DEFAULT NULL,
  `sheet_synced_at` timestamp NULL DEFAULT NULL,
  `sheet_sync_error` text DEFAULT NULL,
  `quotation_id` bigint(20) unsigned NOT NULL,
  `total_amount` decimal(8,2) NOT NULL,
  `product_cost_price` decimal(10,2) DEFAULT NULL,
  `shipping_cost_real` decimal(10,2) DEFAULT NULL,
  `rejection_loss_cost` decimal(10,2) DEFAULT NULL,
  `net_profit_or_loss` decimal(10,2) DEFAULT NULL,
  `refund_amount` decimal(10,2) DEFAULT 0.00,
  `refund_proof_path` varchar(255) DEFAULT NULL,
  `initial_estimated_product_cost` decimal(10,2) DEFAULT NULL COMMENT 'Coût produit initial (copié de quotation)',
  `initial_estimated_shipping_cost` decimal(10,2) DEFAULT NULL COMMENT 'Coût transport initial (copié de quotation)',
  `initial_estimated_other_costs` decimal(10,2) DEFAULT NULL COMMENT 'Autres coûts initiaux (copié de quotation)',
  `cost_adjustment_notes` text DEFAULT NULL COMMENT 'Notes sur les ajustements de coûts',
  `status` varchar(255) NOT NULL DEFAULT 'pending',
  `rejection_reason` text DEFAULT NULL,
  `proof_of_payment_path` varchar(255) DEFAULT NULL,
  `tracking_number` varchar(255) DEFAULT NULL,
  `tracking_carrier` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sourcing_orders_user_id_foreign` (`user_id`),
  KEY `sourcing_orders_quotation_id_foreign` (`quotation_id`),
  KEY `sourcing_orders_net_profit_or_loss_index` (`net_profit_or_loss`),
  KEY `sourcing_orders_assigned_to_admin_id_foreign` (`assigned_to_admin_id`),
  KEY `sourcing_orders_shipping_company_id_foreign` (`shipping_company_id`),
  CONSTRAINT `sourcing_orders_assigned_to_admin_id_foreign` FOREIGN KEY (`assigned_to_admin_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `sourcing_orders_quotation_id_foreign` FOREIGN KEY (`quotation_id`) REFERENCES `quotations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sourcing_orders_shipping_company_id_foreign` FOREIGN KEY (`shipping_company_id`) REFERENCES `shipping_companies` (`id`) ON DELETE SET NULL,
  CONSTRAINT `sourcing_orders_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

