CREATE TABLE `sourcing_request_destinations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sourcing_request_id` bigint(20) unsigned NOT NULL,
  `country_id` bigint(20) unsigned NOT NULL,
  `service_id` bigint(20) unsigned NOT NULL,
  `quantity` int(11) NOT NULL,
  `address` varchar(255) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sourcing_request_destinations_sourcing_request_id_foreign` (`sourcing_request_id`),
  KEY `sourcing_request_destinations_country_id_foreign` (`country_id`),
  KEY `sourcing_request_destinations_service_id_foreign` (`service_id`),
  CONSTRAINT `sourcing_request_destinations_country_id_foreign` FOREIGN KEY (`country_id`) REFERENCES `countries` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sourcing_request_destinations_service_id_foreign` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sourcing_request_destinations_sourcing_request_id_foreign` FOREIGN KEY (`sourcing_request_id`) REFERENCES `sourcing_requests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=50 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

